insert into public.products (id, slug, status, price, sale_price, sort_order, details) values ('prod-essential-hoodie-black', 'rootland-essential-hoodie-black', 'active', 1250, null, 0, $json${"name":"RootLand Hoodie Black","nameEn":"RootLand Hoodie Black","nameArabic":"هودي روت لاند أسود","nameAr":"هودي روت لاند أسود","tagline":"Unisex Oversized Plain Hoodie · Soft, Substantial Fleece","taglineEn":"Unisex Oversized Plain Hoodie · Soft, Substantial Fleece","taglineAr":"هودي سادة أوفر سايز للجنسين · فليس ناعم ومريح","description":"An everyday essential designed for longevity and relaxed comfort. Tailored with an honest, oversized unisex cut with zero drawstrings, no prints, and no logos. Crafted from 70% Egyptian cotton and 30% polyester, delivering a soft, substantial fleece that holds its shape and keeps you warm day in and day out.","descriptionEn":"An everyday essential designed for longevity and relaxed comfort. Tailored with an honest, oversized unisex cut with zero drawstrings, no prints, and no logos. Crafted from 70% Egyptian cotton and 30% polyester, delivering a soft, substantial fleece that holds its shape and keeps you warm day in and day out.","descriptionArabic":"هودي روت لاند الأساسي باللون الأسود. قصة أوفر سايز مريحة ومناسبة للجنسين، بدون حبال وبدون أي طباعة أو لوجو. مصنوع من 70% قطن مصري، 30% بوليستر ليمنحك ملمس فليس ناعم ومريح يدوم معك كل يوم.","descriptionAr":"هودي روت لاند الأساسي باللون الأسود. قصة أوفر سايز مريحة ومناسبة للجنسين، بدون حبال وبدون أي طباعة أو لوجو. مصنوع من 70% قطن مصري، 30% بوليستر ليمنحك ملمس فليس ناعم ومريح يدوم معك كل يوم.","currency":"EGP","isBestSeller":true,"isNewArrival":false,"isLimited":false,"primaryImage":"/src/assets/images/hoodie_essential_black.webp","secondaryImage":"/src/assets/images/hoodie_black_back.webp","gallery":["/src/assets/images/hoodie_essential_black.webp","/src/assets/images/hoodie_black_back.webp","/src/assets/images/hoodie_black_fabric.webp","/src/assets/images/lifestyle_rooftop_sunset.webp","/src/assets/images/lifestyle_zamalek_street.webp","/src/assets/images/lifestyle_hands_folding.webp"],"colors":[{"name":"Black","hex":"#161616","nameEn":"Black","nameAr":"أسود"}],"sizes":["L","XL","XXL"],"specifications":{"fabricWeight":"Soft, Substantial Fleece","fabricWeightEn":"Soft, Substantial Fleece","fabricWeightAr":"فليس ناعم ومريح","composition":"70% Egyptian cotton, 30% polyester","compositionEn":"70% Egyptian cotton, 30% polyester","compositionAr":"70% قطن مصري، 30% بوليستر","weave":"Plush brushed fleece interior with smooth knit surface","weaveEn":"Plush brushed fleece interior with smooth knit surface","weaveAr":"سطح خارجي محبوك ناعم وبطانة داخلية فليس مريحة","ribbing":"Durable stretch ribbing at cuffs and hem","ribbingEn":"Durable stretch ribbing at cuffs and hem","ribbingAr":"حياكة مرنة متينة عند المعصمين والحافة السفلية","origin":"Designed and crafted in Egypt","originEn":"Designed and crafted in Egypt","originAr":"تصميم وحياكة متقنة في مصر","shrinkage":"Standard cold machine wash; hang dry","shrinkageEn":"Standard cold machine wash; hang dry","shrinkageAr":"غسيل آلي بماء بارد مع التجفيف بالتعليق"},"fitDescription":"Unisex oversized fit. Designed with dropped shoulders and a clean silhouette with no drawstrings. People who normally wear M get a relaxed oversized fit in L. People who wear S may find L too big.","fitDescriptionEn":"Unisex oversized fit. Designed with dropped shoulders and a clean silhouette with no drawstrings. People who normally wear M get a relaxed oversized fit in L. People who wear S may find L too big.","fitDescriptionAr":"قصة أوفر سايز للجنسين مع نزول في الكتفين ومظهر نقي بدون حبال. من يرتدي عادة مقاس M يحصل على قصة أوفر سايز مريحة في مقاس L. من يرتدي مقاس S قد يجد مقاس L كبيراً عليه.","careInstructions":["Machine wash cold inside out at 30°C","Wash with similar dark colors","Do not tumble dry; hang dry naturally","Warm iron on reverse if needed, do not bleach"],"careInstructionsEn":["Machine wash cold inside out at 30°C","Wash with similar dark colors","Do not tumble dry; hang dry naturally","Warm iron on reverse if needed, do not bleach"],"careInstructionsAr":["غسيل آلي بماء بارد على مقلوب القطعة عند 30 درجة مئوية","الغسيل مع ألوان داكنة مماثلة","تجنب التجفيف الآلي؛ يفضل التجفيف الطبيعي بالتعليق","كي خفيف على الوجه الداخلي عند الحاجة، بدون مبيضات"],"measurements":[{"size":"L","chestCm":128,"lengthCm":73,"sleeveCm":64,"shoulderCm":60,"chestWidthCm":64,"garmentLengthCm":73,"sleeveLengthCm":64,"standardUkUsChest":"Fits chest 102–107 cm (40–42 in)","recommendedHeightCm":"175 - 185 cm","recommendedWeightKg":"72 - 88 kg"},{"size":"XL","chestCm":136,"lengthCm":75,"sleeveCm":65.5,"shoulderCm":62,"chestWidthCm":68,"garmentLengthCm":75,"sleeveLengthCm":65.5,"standardUkUsChest":"Fits chest 112–117 cm (44–46 in)","recommendedHeightCm":"182 - 192 cm","recommendedWeightKg":"88 - 102 kg"},{"size":"XXL","chestCm":144,"lengthCm":77,"sleeveCm":67,"shoulderCm":64,"chestWidthCm":72,"garmentLengthCm":77,"sleeveLengthCm":67,"standardUkUsChest":"Fits chest 122–127 cm (48–50 in)","recommendedHeightCm":"186 - 198 cm","recommendedWeightKg":"102 - 118 kg"}],"rating":5,"reviewCount":0,"tags":["Unisex","Plain Essentials","Oversized","70/30 Egyptian Cotton Fleece"],"b2bAvailable":true}$json$::jsonb);
