insert into public.products (id, slug, status, price, sale_price, sort_order, details) values ('prod-essential-hoodie-whitegrey', 'rootland-essential-hoodie-whitegrey', 'active', 999, null, 1, $json${"name":"RootLand Hoodie White","nameEn":"RootLand Hoodie White","nameArabic":"هودي روت لاند أبيض","nameAr":"هودي روت لاند أبيض","tagline":"Unisex Oversized Plain Hoodie · Soft, Substantial Fleece","taglineEn":"Unisex Oversized Plain Hoodie · Soft, Substantial Fleece","taglineAr":"هودي سادة أوفر سايز للجنسين · فليس ناعم ومريح","description":"Clean, effortless, and versatile. Our White-Grey oversized hoodie is tailored from 70% Egyptian cotton and 30% polyester to provide a soft, substantial fleece feel. Completely plain with no logos, prints, or drawstrings, built for daily wear across every season.","descriptionEn":"Clean, effortless, and versatile. Our White-Grey oversized hoodie is tailored from 70% Egyptian cotton and 30% polyester to provide a soft, substantial fleece feel. Completely plain with no logos, prints, or drawstrings, built for daily wear across every season.","descriptionArabic":"هودي روت لاند الأساسي باللون الرمادي الفاتح. تصميم هادئ ونظيف بدون أي طباعة أو لوجو وبدون حبال. مصنوع من 70% قطن مصري، 30% بوليستر بملمس فليس ناعم ومريح ومناسب للجنسين.","descriptionAr":"هودي روت لاند الأساسي باللون الرمادي الفاتح. تصميم هادئ ونظيف بدون أي طباعة أو لوجو وبدون حبال. مصنوع من 70% قطن مصري، 30% بوليستر بملمس فليس ناعم ومريح ومناسب للجنسين.","currency":"EGP","isNewArrival":true,"isBestSeller":false,"isLimited":false,"primaryImage":"/src/assets/images/hoodie_essential_whitegrey.webp","secondaryImage":"/src/assets/images/hoodie_whitegrey_back.webp","gallery":["/src/assets/images/hoodie_essential_whitegrey.webp","/src/assets/images/hoodie_whitegrey_back.webp","/src/assets/images/hoodie_whitegrey_fabric.webp","/src/assets/images/lifestyle_cairo_cafe.webp","/src/assets/images/lifestyle_cutting_table.webp","/src/assets/images/lifestyle_hands_folding.webp"],"colors":[{"nam