ed, do not bleach"],"careInstructionsAr":["غسيل بماء بارد عند 30 درجة مئوية أو أقل","غسيل القطعة على مقلوبها مع ألوان فاتحة","التجفيف بالتعليق بعيداً عن أشعة الشمس القوية المباشرة","كي خفيف على الوجه الداخلي عند الرغبة، بدون مبيضات"],"measurements":[{"size":"L","chestCm":128,"lengthCm":73,"sleeveCm":64,"shoulderCm":60,"chestWidthCm":64,"garmentLengthCm":73,"sleeveLengthCm":64,"standardUkUsChest":"Fits chest 102–107 cm (40–42 in)","recommendedHeightCm":"175 - 185 cm","recommendedWeightKg":"72 - 88 kg"},{"size":"XL","chestCm":136,"lengthCm":75,"sleeveCm":65.5,"shoulderCm":62,"chestWidthCm":68,"garmentLengthCm":75,"sleeveLengthCm":65.5,"standardUkUsChest":"Fits chest 112–117 cm (44–46 in)","recommendedHeightCm":"182 - 192 cm","recommendedWeightKg":"88 - 102 kg"},{"size":"XXL","chestCm":144,"lengthCm":77,"sleeveCm":67,"shoulderCm":64,"chestWidthCm":72,"garmentLengthCm":77,"sleeveLengthCm":67,"standardUkUsChest":"Fits chest 122–127 cm (48–50 in)","recommendedHeightCm":"186 - 198 cm","recommendedWeightKg":"102 - 118 kg"}],"rating":5,"reviewCount":0,"tags":["Unisex","Plain Essentials","Oversized","70/30 Egyptian Cotton Fleece"],"b2bAvailable":true}$json$::jsonb);
